/*
 * Tests for source/luma_config.c.
 *
 * The fixtures are hand-written: they follow the layout of a Luma3DS v13
 * config.ini (sections, key names, "key = value") but are not copies of it.
 */
#include <stdlib.h>

#include "luma_config.h"
#include "test.h"

/* A typical file: game patching off, other options around it. */
static const char CONFIG_OFF[] =
	"; generated by Luma3DS\n"
	"\n"
	"[meta]\n"
	"; do not edit\n"
	"config_version_major = 3\n"
	"config_version_minor = 13\n"
	"\n"
	"[boot]\n"
	"autoboot_emunand = 0\n"
	"enable_external_firm_and_modules = 0\n"
	"\n"
	"; IPS support, LayeredFS, ...\n"
	"enable_game_patching = 0\n"
	"app_syscore_threads_on_core_2 = 0\n"
	"splash_position = before payloads\n"
	"\n"
	"[rosalina]\n"
	"hbldr_3dsx_titleid = 000400000d921e00\n"
	"plugin_loader_enabled = 0\n";

/* Parse a string literal. */
static LumaCfgStatus parse(const char *text, LumaCfgInfo *info)
{
	return lumacfg_parse(text, strlen(text), info);
}

/* Run lumacfg_set_game_patching on a copy; returns the edited text (freed by caller). */
static char *set_copy(const char *text, int enabled, LumaCfgStatus *st)
{
	size_t n = strlen(text);
	char *buf = malloc(n + 1);
	memcpy(buf, text, n + 1);
	*st = lumacfg_set_game_patching(buf, n, enabled);
	return buf;
}

static void parses_typical_file(void)
{
	LumaCfgInfo info;
	CHECK(parse(CONFIG_OFF, &info) == LUMACFG_OK);
	CHECK(info.version_major == 3);
	CHECK(info.version_minor == 13);
	CHECK(info.game_patching == 0);
	CHECK(CONFIG_OFF[info.value_offset] == '0');
	/* The offset points into the enable_game_patching line. */
	CHECK(strncmp(CONFIG_OFF + info.value_offset - 23, "enable_game_patching = ", 23) == 0);
}

static void enable_flips_only_one_byte(void)
{
	LumaCfgStatus st;
	char *out = set_copy(CONFIG_OFF, 1, &st);
	CHECK(st == LUMACFG_OK);

	size_t diffs = 0;
	for (size_t i = 0; i < sizeof(CONFIG_OFF) - 1; i++)
		diffs += out[i] != CONFIG_OFF[i];
	CHECK(diffs == 1);
	CHECK(strstr(out, "enable_game_patching = 1\n") != NULL);

	LumaCfgInfo info;
	CHECK(parse(out, &info) == LUMACFG_OK && info.game_patching == 1);

	/* And back off again. */
	CHECK(lumacfg_set_game_patching(out, strlen(out), 0) == LUMACFG_OK);
	CHECK_STR(out, CONFIG_OFF);
	free(out);
}

static void keeps_crlf_and_spacing(void)
{
	const char *text =
		"[meta]\r\nconfig_version_major=3\r\nconfig_version_minor=13\r\n"
		"[boot]\r\n\tenable_game_patching\t=\t0\t\r\n";
	/* The indented key comes right after a section header, so it is a normal
	 * key line, not a continuation. */
	LumaCfgStatus st;
	char *out = set_copy(text, 1, &st);
	CHECK(st == LUMACFG_OK);
	CHECK(strstr(out, "\tenable_game_patching\t=\t1\t\r\n") != NULL);
	free(out);
}

static void skips_utf8_bom(void)
{
	const char *text = "\xEF\xBB\xBF[meta]\nconfig_version_major = 3\n"
	                   "[boot]\nenable_game_patching = 1\n";
	LumaCfgInfo info;
	CHECK(parse(text, &info) == LUMACFG_OK);
	CHECK(info.game_patching == 1);
}

static void accepts_colon_and_inline_comment(void)
{
	const char *text = "[meta]\nconfig_version_major : 3 ; note\n"
	                   "[boot]\nenable_game_patching : 0 ; off\n";
	LumaCfgInfo info;
	CHECK(parse(text, &info) == LUMACFG_OK);
	CHECK(info.version_major == 3 && info.game_patching == 0);
	CHECK(text[info.value_offset] == '0');
}

static void key_only_counts_in_boot(void)
{
	/* Same key in another section must not be touched. */
	const char *text =
		"[meta]\nconfig_version_major = 3\n"
		"[misc]\nenable_game_patching = 0\n"
		"[boot]\nenable_game_patching = 1\n";
	LumaCfgInfo info;
	CHECK(parse(text, &info) == LUMACFG_OK);
	CHECK(info.game_patching == 1);
	CHECK(info.value_offset == strlen(text) - 2);
}

static void rejects_missing_or_wrong_version(void)
{
	LumaCfgInfo info;
	CHECK(parse("[boot]\nenable_game_patching = 0\n", &info) == LUMACFG_ERR_NO_VERSION);
	CHECK(parse("[meta]\nconfig_version_major = 2\n[boot]\nenable_game_patching = 0\n", &info)
	      == LUMACFG_ERR_UNSUPPORTED_VERSION);
	CHECK(parse("[meta]\nconfig_version_major = x\n[boot]\nenable_game_patching = 0\n", &info)
	      == LUMACFG_ERR_UNSUPPORTED_VERSION);
	/* Version keys outside [meta] don't count. */
	CHECK(parse("[boot]\nconfig_version_major = 3\nenable_game_patching = 0\n", &info)
	      == LUMACFG_ERR_NO_VERSION);
}

static void rejects_missing_key(void)
{
	LumaCfgInfo info;
	CHECK(parse("[meta]\nconfig_version_major = 3\n[boot]\nautoboot_emunand = 0\n", &info)
	      == LUMACFG_ERR_NO_KEY);
	CHECK(parse("", &info) == LUMACFG_ERR_NO_VERSION);
}

static void rejects_bad_values(void)
{
	static const char *values[] = {"", "2", "01", "true", "1 # x", "0;x"};
	for (size_t i = 0; i < sizeof(values) / sizeof(values[0]); i++)
	{
		char text[128];
		snprintf(text, sizeof(text),
		         "[meta]\nconfig_version_major = 3\n[boot]\nenable_game_patching = %s\n",
		         values[i]);
		LumaCfgInfo info;
		CHECK(parse(text, &info) == LUMACFG_ERR_BAD_VALUE);
	}
}

static void rejects_duplicates_and_continuations(void)
{
	LumaCfgInfo info;
	CHECK(parse("[meta]\nconfig_version_major = 3\n[boot]\n"
	            "enable_game_patching = 0\nenable_game_patching = 1\n", &info)
	      == LUMACFG_ERR_DUPLICATE_KEY);
	/* inih reads an indented line after a key as a second value for it. */
	CHECK(parse("[meta]\nconfig_version_major = 3\n[boot]\n"
	            "enable_game_patching = 0\n  1\n", &info)
	      == LUMACFG_ERR_DUPLICATE_KEY);
	/* ...but an indented comment is just a comment. */
	CHECK(parse("[meta]\nconfig_version_major = 3\n[boot]\n"
	            "enable_game_patching = 0\n  ; note\n", &info)
	      == LUMACFG_OK);
}

static void failed_edit_leaves_text_alone(void)
{
	const char *text = "[meta]\nconfig_version_major = 4\n[boot]\nenable_game_patching = 0\n";
	LumaCfgStatus st;
	char *out = set_copy(text, 1, &st);
	CHECK(st == LUMACFG_ERR_UNSUPPORTED_VERSION);
	CHECK_STR(out, text);
	free(out);
}

static void handles_text_without_trailing_newline(void)
{
	const char *text = "[meta]\nconfig_version_major = 3\n[boot]\nenable_game_patching = 0";
	LumaCfgInfo info;
	CHECK(parse(text, &info) == LUMACFG_OK);
	CHECK(info.value_offset == strlen(text) - 1);
	/* Only the first `len` bytes are read: cutting the value off fails. */
	CHECK(lumacfg_parse(text, strlen(text) - 1, &info) == LUMACFG_ERR_BAD_VALUE);
}

static void status_strings_exist(void)
{
	for (int s = LUMACFG_OK; s <= LUMACFG_ERR_BAD_VALUE; s++)
		CHECK(strcmp(lumacfg_status_str((LumaCfgStatus)s), "unknown error") != 0);
}

void test_luma_config(void)
{
	parses_typical_file();
	enable_flips_only_one_byte();
	keeps_crlf_and_spacing();
	skips_utf8_bom();
	accepts_colon_and_inline_comment();
	key_only_counts_in_boot();
	rejects_missing_or_wrong_version();
	rejects_missing_key();
	rejects_bad_values();
	rejects_duplicates_and_continuations();
	failed_edit_leaves_text_alone();
	handles_text_without_trailing_newline();
	status_strings_exist();
}
